import {collectionPath,collectionReturn} from './collection-navigation.js';
import {updatePageFrame} from './page-shell.js';
import {setupIdentity,mountHomeRows,disposeShelves} from './identity.js';
import {artistOffer, mountArtistOffer} from './artist.js';
import {setupShopCore} from './core.js';



const shopPaths=/^\/(?:collections(?:\/.*)?|product\/[a-z0-9-]+|wuensche|account|login|register|downloads|checkout|guest|success\/[^/]+|info|admin|kontakt)?\/?$/;

function routeHash(){return '#'+(location.pathname.replace(/^\/|\/$/g,'')||'home');}

function routePath(value){const p=value.replace(/^\/#|^#/,'/');return p==='/home'?'/':p;}

function navigate(value,replace=false){
 const destination=routePath(value);let state=null;
 if(!replace&&/^\/collections(?:\/|$)/.test(location.pathname)){
  history.replaceState({...history.state,scrollY:window.scrollY},'',location.href);
  if(/^\/product\//.test(destination))state={collectionReturn:location.pathname+location.search,collectionScroll:window.scrollY};
 }else if(destination===history.state?.collectionReturn)state={scrollY:history.state.collectionScroll||0};
 history[replace?'replaceState':'pushState'](state,'',destination);route();
}
if('scrollRestoration' in history)history.scrollRestoration='manual';

function migrateHash(){if(location.hash&&/^#(?:home|collections|product|wuensche|account|login|register|downloads|checkout|guest|success|info|admin|kontakt)(?:\/|$)/.test(location.hash)){history.replaceState(null,'',routePath(location.hash));}}

migrateHash();window.addEventListener('hashchange',()=>{migrateHash();route();});

document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&!u.hash&&shopPaths.test(u.pathname)){event.preventDefault();navigate(u.pathname+u.search);}});

import {mountSlider, disposeSlider} from './slider.js';

import { products as initialProducts, money } from './catalog.js';

let catalogReady=false,catalogFinished=false;let products=[...initialProducts];let storefrontSettings={categories:['Wallpaper','Streaming','Sonstiges'],productSort:'newest'};

const $=s=>document.querySelector(s),view=$('#view'),dialog=$('#cartDialog');

const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};

let cart=read('nm-cart',[]); if(!Array.isArray(cart))cart=[];cart=cart.filter(id=>typeof id==='string'&&/^[a-z0-9-]{1,48}$/.test(id));cart=[...new Set(cart)];

let orders=read('nm-demo-orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&Array.isArray(o.items)&&typeof o.id==='string'&&Number.isFinite(o.date));

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const save=()=>{try{localStorage.setItem('nm-cart',JSON.stringify(cart));localStorage.setItem('nm-demo-orders',JSON.stringify(orders))}catch{}$('#cartCount').textContent=cart.length};

const find=id=>products.find(p=>p.id===id);const selected=()=>cart.map(find).filter(Boolean);const total=()=>selected().reduce((n,p)=>n+p.price,0);

let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}

function add(id){if(id==='designstudio'){location.href='/gestalter.html';return;}if(!find(id))return;if(cart.includes(id)){toast('Dieses Produkt liegt bereits im Warenkorb.');return}cart.push(id);save();toast('Zum Warenkorb hinzugefügt.');renderCart()}

const card=p=>`<article class="card ${p.packageReady?'collection-card':''}"><a class="card-image" href="/product/${p.id}" aria-label="${p.name} ansehen"><img src="${p.image}" alt="${p.name} – Produktvorschau" loading="lazy"></a><div class="card-body"><h3><a href="/product/${p.id}">${p.name}</a></h3><p>${p.contents}</p><div class="card-bottom"><span class="price">${money(p.price)}</span><button class="icon-button" data-add="${p.id}" aria-label="${p.name} in den Warenkorb">＋</button></div></div></article>`;

function homeShelves(){const categories=['Webtemplates','Wallpaper','Streaming','Flyer & Werbung','Poster'];return `<section class="panel collections home-shelves"><div class="section-title"><div><h2>Entdecke die Kollektionen</h2><p>Ausgewählte Designs für deinen digitalen Alltag.</p></div><a href="/collections">Alle Produkte anzeigen →</a></div>${categories.map((category,i)=>{const list=products.filter(p=>p.category===category).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));return `<section class="category-shelf" aria-labelledby="shelf-title-${i}"><h3 class="neon-divider" id="shelf-title-${i}"><span>${esc(category)}</span></h3><div class="shelf-wrap"><button class="shelf-arrow shelf-prev" aria-label="${esc(category)} zurückblättern" aria-controls="shelf-track-${i}">‹</button><div class="shelf-track" id="shelf-track-${i}" tabindex="0" aria-label="${esc(category)} Produkte">${list.length?list.map(card).join(''):'<p>Neue Designs folgen bald.</p>'}</div><button class="shelf-arrow shelf-next" aria-label="${esc(category)} weiterblättern" aria-controls="shelf-track-${i}">›</button></div><a class="shelf-all" href="/collections/${encodeURIComponent(category)}">Alle ${esc(category)} ansehen →</a></section>`}).join('')}</section>`;}
const collection=(full=false)=>`<section class="panel collections"><div class="section-title"><div><h2>${full?'Alle Kollektionen':'Entdecke die Kollektionen'}</h2><p>Ausgewählte Designs für deinen digitalen Alltag.</p></div>${full?'<input class="search" id="search" type="search" aria-label="Produkte suchen" placeholder="Kollektion suchen …">':'<a href="/collections">Alle Produkte anzeigen →</a>'}</div>${full?`<div class="filters"><button class="chip active" data-filter="Alle">Alle</button>${storefrontSettings.categories.map(c=>`<button class="chip" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div>`:''}<div class="grid" id="productGrid">${products.map(card).join('')}</div><p class="muted">Digitale Kollektionen von NeonMind · Sichere Zahlung und geschützte Downloads.</p><div class="benefits"><div>↓ &nbsp; Dein Downloadbereich<br><span>Deine Käufe an einem Ort</span></div><div>&infin; &nbsp; Für deine Kreativität<br><span>Wallpaper, Panels und mehr</span></div><div>&#9825; &nbsp; Mit Liebe zum Detail<br><span>Der Look von NeonMind</span></div></div></section>`;

function home(){const latest=[...products].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,3);view.innerHTML=`<section class="hero-slider" aria-label="NeonMind Highlights" aria-roledescription="Karussell"><div class="hero-track"><section class="hero-slide hero-intro"><div class="hero-copy"><span class="kicker">Digitale Designs · NeonMind</span><h1>Dein Bildschirm.<br><em>Deine Welt.</em></h1><p>Digitale Designs von NeonMind.</p><a class="button primary" href="/collections">Kollektion entdecken <span>→</span></a><div class="facts"><span><b>&#9639;</b> Eigene<br>Designwelten</span><span><b>&#9671;</b> Sorgfältige<br>Gestaltung</span><span><b>&#9647;</b> Für PC &<br>Smartphone</span></div></div></section><section class="hero-slide hero-latest"><div class="slider-heading"><span class="kicker">Frisch im Shop</span><h2>Deine neuesten Designwelten.</h2><p>Entdecke die drei zuletzt hinzugefügten Produkte.</p></div><div class="latest-grid">${latest.map(p=>`<a class="latest-card" href="/product/${p.id}"><img src="${p.image}" alt="${p.name} Vorschau"><span><strong>${p.name}</strong><small>${money(p.price)} · ${esc(p.category)}</small></span></a>`).join('')}</div></section><section class="hero-slide hero-worlds"><div class="hero-copy"><span class="kicker">Dein Stil · Deine Auswahl</span><h2>Bring Farbe<br>in deinen Alltag.</h2><p>Von deinem Bildschirm bis zu deinem Stream: Finde die Designwelt, die zu dir passt.</p><div class="world-links">${["Webtemplates","Wallpaper","Streaming","Flyer & Werbung","Poster"].map(c=>`<a class="button" href="/collections/${encodeURIComponent(c)}">${esc(c)} →</a>`).join('')}</div><a class="button primary" href="https://neonmind-ai.com/">Mehr von NeonMind entdecken →</a></div></section><section class="hero-slide hero-wishes"><div class="hero-copy"><span class="kicker">Deine Idee · Unser Design</span><h2>Deine Wünsche.<br><em>Dein ganz eigener Look.</em></h2><p>Du hast eine Idee, aber noch kein passendes Design? Wir gestalten individuelle Wallpaper, Stream-Pakete, Logos und Websites – oder passen eine Kollektion an deinen Stil an.</p><a class="button primary" href="/wuensche">Dein Projekt anfragen →</a><small>Unverbindlich anfragen · Umsetzung und Angebot nach gemeinsamer Abstimmung</small></div><div class="wish-art" aria-hidden="true"><div class="wish-orbit"></div><div class="wish-card wish-card-back"><span>01 / DEINE IDEE</span><i></i><i></i><i></i></div><div class="wish-card wish-card-front"><span>02 / UNSER DESIGN</span><b>MAKE IT<br><em>YOURS.</em></b><div class="wish-swatches"><i></i><i></i><i></i></div></div><div class="wish-badge">&#10022; FÜR DICH GESTALTET</div></div></section></div><button class="slider-arrow slider-prev" aria-label="Vorherige Ansicht">&#8249;</button><button class="slider-arrow slider-next" aria-label="Nächste Ansicht">›</button><div class="slider-controls"><div class="slider-dots" role="group" aria-label="Slideransicht auswählen">${['Dein Bildschirm. Deine Welt.','Die drei neuesten Produkte','Deine Designwelten','Deine Wünsche'].map((name,i)=>`<button class="slider-dot" aria-label="${name}" data-slide="${i}"></button>`).join('')}</div><button class="slider-pause" aria-label="Automatischen Wechsel pausieren">&#8545;</button></div></section>${homeShelves()}`;mountSlider($('.hero-slider'));mountHomeRows();}



function product(id){const p=find(id);const returnPath=collectionReturn(history.state?.collectionReturn,p?.category||'Alle');if(!p){view.innerHTML='<div class="panel page empty"><h1>Produkt nicht gefunden</h1><a class="button" href="/collections">Zur Übersicht</a></div>';return}view.innerHTML=`<section class="page"><a class="button collection-back" href="${esc(returnPath)}">← Zurück zur Kollektion</a><div class="breadcrumb"><a href="/">Entdecken</a> › <a href="${esc(returnPath)}">${esc(p.category)}</a> › ${p.name}</div><div class="panel product-layout"><div><img class="product-image" src="${p.image}" alt="${p.name} große Vorschau"><p class="muted">${p.category==='Designservice'?'Persönliche Dienstleistung · kein Sofortdownload':p.packageReady?'Fertiges Downloadpaket · Vorschaubilder in reduzierter Auflösung':'Motivvorschau · Produktpaket in Vorbereitung'}</p></div><div class="product-copy"><span class="kicker">${esc(p.category)} / NeonMind</span><h1>${p.name}</h1><p>${p.description}</p>${artistOffer(p)}${p.category==='Flyer & Werbung'?'<div class="notice"><strong>Deine Veranstaltung. Dein Flyer.</strong><p>Bearbeitbare Texte, drei Farben und passende Social- und Druckformate. Individuelle Anpassung auf Anfrage.</p><a class="button primary" href="/demos/'+encodeURIComponent(p.id)+'/index.html" target="_blank" rel="noopener">Paketvorschau öffnen ↗</a> <a class="button" href="/wuensche">Anpassung anfragen →</a></div>':''}${p.category==='Kanal & Social Media'?'<div class="notice"><strong>Dein Kanal. Dein eigener Auftritt.</strong><p>Passende Profilbilder, Titelbilder, Beiträge und Stream-Grafiken für sechs Plattformen. In der Live-Demo kannst du die vorbereiteten Titelbild-Zuschnitte vergleichen. Individuelle Anpassung mit deinem Namen, Logo oder Foto auf Anfrage.</p><a class="button primary" href="/demos/'+encodeURIComponent(p.id)+'/index.html" target="_blank" rel="noopener">Live-Demo öffnen ↗</a> <a class="button" href="/wuensche">Anpassung anfragen →</a></div>':''}${p.category==='Webtemplates'?'<div class="notice"><strong>Dein Design. Dein Websystem.</strong><p>Auf Anfrage passen wir dieses Design an Joomla, Webspell oder andere CMS- und Websysteme an. Teile uns System, Version und Wünsche mit. Wir prüfen die Umsetzung und erstellen ein individuelles Angebot. Installation und Zusatzfunktionen separat nach Vereinbarung.</p><a class="button primary" href="/demos/'+encodeURIComponent(p.id)+'/index.html" target="_blank" rel="noopener">Live-Demo öffnen ↗</a> <a class="button" href="/anpassung.html?produkt='+encodeURIComponent(p.id)+'">Anpassung anfragen →</a></div>':''}<span class="price">${money(p.price)}</span><span class="muted"></span><ul class="detail-list"><li>${p.contents}</li><li>${p.formats}</li><li>${p.license?p.license:p.category==='Designservice'?'Anpassung eines vorhandenen Artist-Launch-Pakets für einen Künstler; Übergabe und Nutzungsrechte gemäß Basispaket.':p.packageReady?(['designstudio','radio-launch','clan-launch'].includes(p.id)?'Gestaltung und Nutzung für einen eigenen privaten oder kommerziellen Auftritt; keine Weitergabe oder Weiterverkauf dieses Vorlagenpakets. Schrift gemäß OFL.':['System & UI','UI Assets'].includes(p.category)?'Nutzung in eigenen privaten und kommerziellen App-/Webprojekten; kein Weiterverkauf des unveränderten Pakets.':p.category==='Webtemplates'?'Nutzung und Bearbeitung für eine eigene private oder kommerzielle Website; keine Weitergabe als Vorlagenpaket. Schriften gemäß OFL.':['Streaming','Kanal & Social Media','Artist & Branding'].includes(p.category)?'Anpassung und Nutzung auf dem eigenen Kanal, auch für kommerzielle Profile und monetarisierte Streams; keine Weitergabe oder Weiterverkäufe der Vorlagendateien.':['emerald-afterglow','neon-odyssey'].includes(p.id)?'Persönliche Nutzung als Wallpaper und auf dem eigenen Streaming-Kanal, auch monetarisiert; keine Weitergabe oder Weiterverkäufe der Vorlagendateien.':'Private Nutzung auf eigenen Geräten und private Ausdrucke; kein Weiterverkauf oder Weitergeben der Dateien.'):'Nutzungsrechte: werden vor Verkaufsstart festgelegt'}</li></ul>${p.id==='artist-launch'?'':`<button class="button primary" data-add="${p.id}">＋ In den Warenkorb</button>`}<p class="notice">Vollständige Downloadpakete liegen im privaten Dateispeicher und werden nach bestätigter Zahlung freigegeben. Persönliche Designleistungen werden nach Bearbeitung geliefert.</p></div></div><section class="panel product-gallery" id="productGallery" hidden><h2>Einblicke in dieses Paket</h2><p class="muted">Öffentliche Vorschauen · Die Originaldateien liegen im privaten Downloadpaket.</p><div class="gallery-grid"></div></section></section>`;loadGallery(p.id);mountArtistOffer(add);}

async function loadGallery(id){try{const response=await fetch('/api/gallery/'+id);if(!response.ok)return;const pictures=await response.json();if(routeHash()!=='#product/'+id||!pictures.length)return;const section=$('#productGallery');section.hidden=false;section.querySelector('.gallery-grid').innerHTML=pictures.map(p=>`<figure><img src="${esc(p.image+(['radio-launch','clan-launch'].includes(id)?'?v=fixed2':''))}" alt="${esc(p.title)}" loading="lazy"><figcaption>${esc(p.title)}</figcaption></figure>`).join('')}catch{}}

function renderCart(){const items=selected();$('#cartContent').innerHTML=items.length?`${items.map(p=>`<div class="cart-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><button class="remove" data-remove="${p.id}">Entfernen</button></div><span class="price">${money(p.price)}</span></div>`).join('')}<div class="summary-line total"><span>Gesamt</span><span>${money(total())}</span></div><p class="muted">Digitale Produkte · Persönliche Leistungen nach Vereinbarung</p><div class="cart-actions"><a class="button primary" href="/checkout" id="checkoutLink">Zur Kasse →</a><button class="button" id="continueShopping">Weiter entdecken</button></div>`:'<div class="empty"><h2>Hier ist noch Platz.</h2><p class="muted">Entdecke deine nächste Designwelt.</p><button class="button primary" id="continueShopping">Kollektionen ansehen</button></div>'}

function previewCheckout(){if(!cart.length){view.innerHTML='<div class="panel page empty"><h2>Dein Warenkorb ist leer.</h2><a class="button primary" href="/collections">Kollektionen entdecken</a></div>';return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="/collections">Kollektionen</a> › Testkasse</div><h1 style="font-size:40px">Deine Auswahl.</h1><p class="muted">Ein Testdurchlauf ohne Zahlung und ohne persönliche Daten.</p><div class="checkout-grid"><form class="panel" id="checkoutForm"><h2>Testkauf</h2><p>Der echte Zahlungsanschluss wird nach Einrichtung deines Betreiberkontos ergänzt.</p><label class="field">Testablauf<select id="testResult"><option value="success">Erfolgreicher Testkauf</option><option value="pending">Zahlung ausstehend simulieren</option><option value="failed">Fehlgeschlagene Zahlung simulieren</option></select></label><label class="check"><input type="checkbox" required>Ich verstehe, dass dies eine Vorschau mit Beispielprodukten ist und kein echter Kauf stattfindet.</label><button class="button primary" type="submit">Testkauf durchführen</button><p class="notice">Die Testhistorie wird nur in diesem Browser gespeichert. Sie bestätigt keine echte Zahlung und schaltet keine privaten Produkte frei.</p></form><aside class="panel"><h2>Bestellübersicht</h2>${selected().map(p=>`<div class="summary-line"><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Beispielgesamtpreis</span><span>${money(total())}</span></div><p class="muted">Heute zahlst du: 0,00 €</p></aside></div></section>`;$('#checkoutForm').addEventListener('submit',e=>{e.preventDefault();const status=$('#testResult').value;if(status!=='success'){view.innerHTML=`<div class="panel page success"><h2>${status==='pending'?'Testzahlung ausstehend':'Testzahlung fehlgeschlagen'}</h2><p>Es wurden keine Downloads freigegeben.</p><button class="button primary" id="retryCheckout">Zurück zur Testkasse</button></div>`;return}const order={id:crypto.randomUUID(),date:Date.now(),items:[...cart],mode:'demo'};orders.unshift(order);cart=[];save();navigate('#success/'+order.id)})}

function previewDownloads(){const bought=[...new Set(orders.flatMap(o=>o.items))].map(find).filter(Boolean);view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">Deine Designbibliothek</span><h1 style="font-size:42px">Meine Downloads</h1><p class="muted">Hier findest du die Demodateien deiner Testkäufe.</p>${bought.length?bought.map(p=>`<article class="download-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><p>Ein Demobild · Öffentliches Vorschauasset</p><span class="status">✓ Testkauf abgeschlossen</span></div>${(order.status==='paid'||order.status==='test_paid')&&p.category!=='Designservice'?`<button class="button primary" data-paid-download="${esc(p.id)}" data-order-id="${esc(order.id)}">Paket herunterladen ↓</button>`:''}<a class="button" href="${p.demo}" ${/\.(png|jpe?g|webp)$/i.test(p.demo)?`download="NeonMind-${p.id}-Demo.png"`: 'target="_blank" rel="noopener"'}>${/\.(png|jpe?g|webp)$/i.test(p.demo)?'↓ Demobild herunterladen':'Live-Vorschau öffnen ↗'}</a></article>`).join(''):'<div class="empty"><h2>Deine Sammlung beginnt hier.</h2><p class="muted">Nach einem Testkauf erscheint dein Demobild in diesem Bereich.</p><a class="button primary" href="/collections">Designs entdecken</a></div>'}<p class="notice">Im fertigen Shop werden private Downloads serverseitig freigegeben. Diese Vorschau verwendet ausschließlich öffentliche Demobilder.</p>${orders.length?'<button class="button" id="resetDemo">Testhistorie löschen</button>':''}</div></section>`}

function previewRoute(){dialog.close();const [page,id]=(routeHash().slice(1)||'home').split('/');if(page==='wuensche')wishesPage();else if(page==='product')product(id);else if(page==='collections'){view.innerHTML='<div class="page">'+collection(true)+'</div>';let filter=id?decodeURIComponent(id):'Alle';$('#search').value=new URLSearchParams(location.search).get('q')||'';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));const update=()=>{const q=$('#search').value.toLowerCase();const result=products.filter(p=>(filter==='Alle'||p.category===filter)&&p.name.toLowerCase().includes(q));$('#productGrid').innerHTML=result.length?result.map(card).join(''):'<p class="muted">Keine passende Kollektion gefunden.</p>'};update();const remember=()=>history.replaceState(history.state,'',collectionPath(filter,$('#search').value));$('#search').addEventListener('input',()=>{remember();update()});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;remember();document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));update()}))}else if(page==='checkout')checkout();else if(page==='downloads')downloads();else if(page==='success'){const order=orders.find(o=>o.id===id);view.innerHTML=order?'<section class="page panel success"><span class="success-symbol">✓</span><h1 style="font-size:40px">Deine Designs warten.</h1><p>Der Testkauf ist abgeschlossen. Es wurde kein Geld abgebucht.</p><a class="button primary" href="/downloads">Zu meinen Downloads →</a></section>':'<div class="panel page empty"><h2>Testbestellung nicht gefunden.</h2><a href="/downloads">Zu den Downloads</a></div>'}else if(page==='info')view.innerHTML='<section class="page"><div class="panel content"><h1 style="font-size:40px">Über den Shop</h1><p>NeonMind Shop ist ein eigenständiges Projekt von NeonMind. Der öffentliche Shop zeigt unsere Designs und Downloadpakete. Der Zahlungsanschluss wird derzeit eingerichtet.</p><h2>Kein aktiver Verkauf</h2><p>Die Kasse wird erst nach Einrichtung des Zahlungsanbieters freigeschaltet. Einige Kollektionen enthalten bereits vollständige private Downloadpakete; ihre Produktseiten zeigen die tatsächlichen Inhalte und Auflösungen. Konten speichern die angegebene E-Mail-Adresse und einen geschützten Passworthash. Der Warenkorb und ältere lokale Testkäufe liegen in deinem Browser. Neue Konto- und Gastbestellungen werden in der Shop-Datenbank gespeichert. Bei Registrierung werden E-Mail-Adresse und geschützter Passworthash gespeichert.</p><h2>Vor dem Verkaufsstart</h2><p>Impressum und Datenschutzhinweise sind im Footer verlinkt. Vor einem aktiven Verkauf werden Verkaufsbedingungen, Widerrufshinweise und die tatsächlichen Geschäftsangaben auf den Verkaufsbetrieb abgestimmt. Der Zahlungsanbieter, E-Mail-Verifizierung, Passwort-Wiederherstellung und Bestellmails sind noch einzurichten. Private Produktdateien liegen bereits im Cloudflare-Dateispeicher.</p><a class="button" href="/">Zurück zum Shop</a></div></section>';else home();document.title=(page==='product'&&find(id)?find(id).name+' · ':'')+'NeonMind Shop';window.scrollTo(0,0)}

document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton)add(addButton.dataset.add);const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==remove.dataset.remove);save();renderCart()}if(e.target.closest('#continueShopping')){dialog.close();navigate('#collections')}if(e.target.closest('#checkoutLink'))dialog.close();if(e.target.closest('#retryCheckout'))checkout();if(e.target.closest('#resetDemo')){orders=[];save();downloads();toast('Testhistorie gelöscht.')}});

$('#cartButton').addEventListener('click',()=>{renderCart();dialog.showModal()});$('#closeCart').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('popstate',route);save();

let accountUser=null,accountCapabilities=null,guestReceipt=read('nm-checkout-receipt',null),purchaseMode='guest';
let paymentPollCount=0;
function pollPendingPayment(order){if(order?.status==='pending'&&order.id===sessionStorage.getItem('nm-payment-return')&&paymentPollCount++<30){const routeAtStart=routeHash();setTimeout(()=>{if(routeHash()===routeAtStart){if(routeAtStart==='#guest')guestPage();else if(routeAtStart==='#downloads')downloads();}},2000);}}

async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw new Error('Kundenkonten sind auf diesem Vorschau-Host noch nicht eingerichtet.')}if(!response.ok)throw new Error(data.error||'Bitte später erneut versuchen.');return data}

async function accountState(){try{accountCapabilities=await api('/api/health');if(accountCapabilities.accountsEnabled)accountUser=(await api('/api/me')).user;else accountUser=null}catch{accountCapabilities={accountsEnabled:false,guestOrdersEnabled:false};accountUser=null}return accountCapabilities}

function formError(error){const el=$('#accountError')||$('#checkoutError');if(el){el.textContent=error.message;el.hidden=false}else toast(error.message)}

function accountNotice(){return '<p class="notice">Kundenkonten werden gerade eingerichtet. Sobald die Shop-Datenbank angeschlossen ist, kannst du dich hier registrieren und deine Käufe dauerhaft abrufen.</p>'}

async function accountPage(kind='account'){await accountState();if((routeHash().slice(1)||'home')!==kind)return;const enabled=accountCapabilities.accountsEnabled;view.innerHTML=`<section class="page"><div class="panel content"><span class="kicker">Dein NeonMind-Bereich</span><h1 style="font-size:40px">${accountUser?'Dein Konto':kind==='register'?'Konto anlegen':'Anmelden'}</h1>${accountUser?`<p>Angemeldet als <strong>${esc(accountUser.email)}</strong></p><a class="button primary" href="/downloads">Meine Käufe & Downloads →</a><p><a href="/guest">Früheren Gastkauf übernehmen</a></p><button class="button" id="logoutAccount">Abmelden</button>`:!enabled?accountNotice():`<p class="muted">Mit einem Konto findest du deine Käufe auch auf anderen Geräten wieder.</p><form id="accountForm"><label class="field" for="accountEmail">E-Mail-Adresse<input id="accountEmail" type="email" maxlength="254" autocomplete="email" required></label><label class="field" for="accountPassword">Passwort<input id="accountPassword" type="password" minlength="12" maxlength="128" autocomplete="${kind==='register'?'new-password':'current-password'}" required></label><p class="muted">Mindestens 12 Zeichen. Deine Bestellungen und Downloads werden geschützt im Shop gespeichert.</p>${kind==='register'?'<label class="field" for="repeatPassword">Passwort wiederholen<input id="repeatPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>':''}<p class="notice">Bewahre dein Passwort sicher auf. Bei Schwierigkeiten hilft der Shop-Kontakt.</p><p id="accountError" class="notice" role="alert" hidden></p><button class="button primary" type="submit">${kind==='register'?'Konto anlegen':'Anmelden'}</button></form><p>${kind==='register'?'<a href="/login">Schon ein Konto? Anmelden →</a>':'<a href="/register">Noch kein Konto? Konto anlegen →</a>'}</p>`}<p><a href="/guest">Als Gast frühere Bestellung öffnen →</a></p></div></section>`;

 if($('#accountForm'))$('#accountForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const password=$('#accountPassword').value;if(kind==='register'&&password!==$('#repeatPassword').value)throw new Error('Die Passwörter stimmen nicht überein.');const result=await api(kind==='register'?'/api/register':'/api/login',{email:$('#accountEmail').value,password});accountUser=result.user;purchaseMode='account';toast(kind==='register'?'Konto angelegt.':'Du bist angemeldet.');navigate(cart.length?'#checkout':'#downloads')}catch(error){formError(error)}finally{button.disabled=false}});

 if($('#logoutAccount'))$('#logoutAccount').addEventListener('click',async()=>{try{await api('/api/logout',{});accountUser=null;purchaseMode='guest';toast('Du bist abgemeldet.');navigate('#account');await accountPage('account')}catch(error){formError(error)}});

}

async function checkout(){
 await accountState();if(routeHash()!=='#checkout')return;
 if(!cart.length){view.innerHTML='<section class="page panel"><h1>Dein Warenkorb ist leer.</h1><a class="button" href="/collections">Produkte entdecken</a></section>';return;}
 let operator=null;if(accountUser){try{operator=await api('/api/admin/payments')}catch{}}
 const live=accountCapabilities.paymentsEnabled;
 view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="/collections">Kollektionen</a> › Kasse</div><h1 style="font-size:40px">Deine Bestellung.</h1><div class="checkout-grid"><form class="panel" id="customerCheckout"><div class="purchase-options"><label class="purchase-option"><input type="radio" name="purchaseMode" value="guest" checked><strong>Als Gast kaufen</strong><span>Dein vertraulicher Bestellschlüssel gibt dir Zugang.</span></label><label class="purchase-option"><input type="radio" name="purchaseMode" value="account"><strong>Mit Kundenkonto</strong><span>Deine Käufe im Konto wiederfinden.</span></label></div><div id="accountChoice"></div><label class="field">E-Mail-Adresse<input id="checkoutEmail" type="email" maxlength="180" autocomplete="email" value="${esc(accountUser?.email||'')}" required></label>${operator?`<label class="field">Betreiber-Testmodus<select id="paymentMode"><option value="admin">Ablauf und echte Paketdownloads testen · 0 € Zahlung</option>${operator.sandboxConfigured?'<option value="sandbox">Stripe-Sandbox · keine echte Zahlung</option>':''}${live?'<option value="live">Echter Kauf · echte Zahlung</option>':''}</select></label><label class="field">Ablauf ohne Stripe testen<select id="operatorScenario"><option value="success">Erfolgreich · Paket freigeben</option><option value="pending">Zahlung ausstehend · kein Download</option><option value="failed">Fehlgeschlagen · kein Download</option><option value="refunded">Erstattet · kein Download</option></select></label><p class="notice">Nur dein Betreiberkonto kann Testbestellungen und Testdownloads verwenden. Sie werden getrennt von bezahlten Bestellungen gekennzeichnet.</p>`:''}${!live&&!operator?'<p class="notice" role="status">Der Zahlungsanschluss wird eingerichtet. Echte Bestellungen sind derzeit noch nicht möglich. Dein Warenkorb bleibt erhalten.</p>':''}<label class="check"><input id="deliveryConsent" type="checkbox" required>Ich habe die Produktbeschreibung und Nutzungsrechte gelesen. Für digitale Dateien wünsche ich die Lieferung unmittelbar nach bestätigter Zahlung. Bei einer persönlichen Designleistung erfolgt die Lieferung nach der vereinbarten Bearbeitung.</label><p id="checkoutError" class="notice" role="alert" hidden></p><button class="button primary" type="submit" ${!live&&!operator?'disabled':''}>${operator?'Ausgewählten Ablauf starten':'Zur sicheren Zahlung →'}</button><p class="muted">Die Zahlung erfolgt bei Stripe. Kartendaten werden nicht im Shop gespeichert. Lastschrift und Rechnungskauf sind nicht aktiviert.</p></form><aside class="panel"><h2>Deine Auswahl</h2>${selected().map(p=>`<div class="summary-line"><span>${esc(p.name)}</span><strong>${money(p.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Gesamtpreis</span><strong>${money(total())}</strong></div><p>Downloadprodukte werden nach bestätigter Zahlung freigegeben. Persönliche Designleistungen haben keinen sofort fertigen Download.</p><p>Bei einem Betreiber-Test wird kein Geld berechnet.</p></aside></div></section>`;
 const choice=()=>{purchaseMode=$('input[name="purchaseMode"]:checked').value;$('#accountChoice').innerHTML=purchaseMode==='account'?(accountUser?`<p>Angemeldet als ${esc(accountUser.email)}</p>`:'<p><a class="button" href="/login">Anmelden</a> <a class="button" href="/register">Konto anlegen</a></p>'):'<p>Bewahre deinen Bestellschlüssel auf. Er wird vor dem Wechsel zur Zahlung auf diesem Gerät gespeichert.</p>';};document.querySelectorAll('[name="purchaseMode"]').forEach(x=>x.onchange=choice);choice();
 $('#customerCheckout').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{
  const mode=$('#paymentMode')?.value||'live';if(purchaseMode==='account'&&!accountUser)throw Error('Bitte zuerst anmelden oder Gastkauf wählen.');
  const receipt=await api(mode==='admin'?'/api/admin/test-order':'/api/checkout',{items:cart,purchaseMode,email:$('#checkoutEmail').value,consent:$('#deliveryConsent').checked,test:mode==='sandbox',result:mode==='admin'?$('#operatorScenario').value:undefined,design:cart.includes(read('nm-design-draft',{})?.productId||'designstudio')?read('nm-design-draft',null):null});
  if(receipt.guestKey){guestReceipt=receipt;localStorage.setItem('nm-checkout-receipt',JSON.stringify(receipt));}
  if(receipt.checkoutUrl){sessionStorage.setItem('nm-payment-return',receipt.order.id);location.assign(receipt.checkoutUrl);return;}
  cart=[];save();navigate('#downloads');
 }catch(error){formError(error);button.disabled=false}};
}


function orderCard(order){return `<section class="order-card"><div class="summary-line"><strong>${order.status==='test_paid'||order.status==='demo'?'Testbestellung':'Bestellung'} ${esc(order.id.slice(0,8))}</strong><span class="status">${esc(({paid:'Zahlung bestätigt',test_paid:'Betreiber-Test · keine Zahlung',pending:'Zahlungsbestätigung ausstehend',refunded:'Erstattet · Zugang gesperrt',disputed:'Zahlung beanstandet · Zugang gesperrt',failed:'Zahlung fehlgeschlagen',expired:'Zahlungsversuch abgelaufen',demo:'Alter Testkauf · keine Zahlung'})[order.status]||order.status)}</span></div><p class="muted">${new Date(order.created_at).toLocaleDateString('de-DE')} · ${money(order.amount)}</p>${order.design?`<div class=notice><b>Dein gespeicherter Designentwurf</b><p><button class=button data-order-design="${esc(encodeURIComponent(JSON.stringify(order.design)))}">Im Designstudio öffnen →</button> <button class=button data-save-design="${esc(encodeURIComponent(JSON.stringify(order.design)))}">Entwurf-JSON herunterladen ↓</button></p></div>`:''}${order.items.map(item=>find(item.product_id)).filter(Boolean).map(p=>`<div class="download-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><p>${p.category==='Designservice'?'Persönliche Bearbeitung · Lieferung nach Abstimmung':order.status==='paid'||order.status==='test_paid'?'Vollständiges privates Paket':'Download wird erst nach bestätigter Zahlung freigegeben.'}</p></div>${(order.status==='paid'||order.status==='test_paid')&&p.category!=='Designservice'?`<button class="button primary" data-paid-download="${esc(p.id)}" data-order-id="${esc(order.id)}">Paket herunterladen ↓</button>`:''}<a class="button" href="${p.demo}" ${/\.(png|jpe?g|webp)$/i.test(p.demo)?`download="NeonMind-${p.id}-Demo.png"`: 'target="_blank" rel="noopener"'}>${/\.(png|jpe?g|webp)$/i.test(p.demo)?'↓ Demobild herunterladen':'Live-Vorschau öffnen ↗'}</a></div>`).join('')}</section>`}

async function downloads(){await accountState();if(routeHash()!=='#downloads')return;if(accountUser){try{const result=await api('/api/orders');pollPendingPayment(result.orders.find(o=>o.id===sessionStorage.getItem('nm-payment-return')));if(result.orders.some(o=>o.id===sessionStorage.getItem('nm-payment-return')&&o.status==='paid')){cart=[];save();sessionStorage.removeItem('nm-payment-return');}view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">Deine Designbibliothek</span><h1 style="font-size:40px">Meine Käufe & Downloads</h1><p class="muted">${esc(accountUser.email)} · Deine Bestellungen und geschützten Downloads</p>${result.orders.length?result.orders.map(orderCard).join(''):'<div class="empty"><h2>Deine Sammlung beginnt hier.</h2><a class="button primary" href="/collections">Designs entdecken</a></div>'}<p><a class="button" href="/guest">Gastbestellung übernehmen</a> <a class="button" href="/account">Mein Konto</a></p></div></section>`}catch(error){toast(error.message)}}else{view.innerHTML='<section class="page panel"><h1>Meine Käufe & Downloads</h1><p>Melde dich an oder öffne deine Gastbestellung mit deinem vertraulichen Bestellschlüssel.</p><a class="button primary" href="/login">Mit Konto anmelden</a> <a class="button" href="/guest">Gastbestellung öffnen</a></section>'}}

async function guestPage(){if(guestReceipt?.guestKey){try{const current=await api('/api/guest/order',{key:guestReceipt.guestKey});guestReceipt.order=current.order;pollPendingPayment(current.order);localStorage.setItem('nm-checkout-receipt',JSON.stringify(guestReceipt));if(current.order.status==='paid'&&current.order.id===sessionStorage.getItem('nm-payment-return')){cart=[];save();sessionStorage.removeItem('nm-payment-return');}}catch{}}await accountState();if(routeHash()!=='#guest')return;view.innerHTML=`<section class="page"><div class="panel content"><span class="kicker">Ohne Kundenkonto</span><h1 style="font-size:40px">Dein Gastzugang</h1>${guestReceipt?`<p>Dein Bestellzugang ist gespeichert. Bewahre diesen Schlüssel auf: Er ermöglicht den späteren Zugang zu dieser Bestellung.</p><label class="field" for="receiptKey">Dein Bestellschlüssel<input id="receiptKey" value="${guestReceipt.guestKey}" readonly></label><button class="button primary" id="saveReceipt">Bestellzugang als Datei speichern</button><div id="guestOrder">${orderCard(guestReceipt.order)}</div>`:''}<form id="guestLookup"><label class="field" for="guestKey">Bestellschlüssel eingeben<input id="guestKey" autocomplete="off" minlength="64" maxlength="64" required ${guestReceipt?'value="'+guestReceipt.guestKey+'"':''}></label><p id="accountError" class="notice" role="alert" hidden></p><button class="button" type="submit">Bestellung öffnen</button></form>${!accountCapabilities.guestOrdersEnabled?accountNotice():''}<div id="lookupResult"></div><p class="notice">Der Schlüssel ist vertraulich. Wer ihn besitzt, kann diese Gastbestellung öffnen. Ohne gespeicherten Schlüssel ist die Wiederherstellung derzeit nicht möglich. E-Mail-Versand folgt vor Verkaufsstart.</p><p>${accountUser?'<button class="button" id="claimGuest">Diese Bestellung meinem Konto zuordnen</button>':'<a href="/register">Konto anlegen</a> oder <a href="/login">anmelden</a>, um einen Gastkauf ins Konto zu übernehmen.'}</p></div></section>`;

 $('#guestLookup').addEventListener('submit',async e=>{e.preventDefault();try{const result=await api('/api/guest/order',{key:$('#guestKey').value.trim()});$('#lookupResult').innerHTML=orderCard(result.order)}catch(error){formError(error)}});

 if($('#claimGuest'))$('#claimGuest').addEventListener('click',async()=>{try{await api('/api/guest/claim',{key:$('#guestKey').value.trim()});guestReceipt=null;toast('Bestellung deinem Konto zugeordnet.');navigate('#downloads')}catch(error){formError(error)}});

 if($('#saveReceipt'))$('#saveReceipt').addEventListener('click',()=>{const blob=new Blob([`NeonMind Shop – Bestellzugang\n\nShop: ${location.origin}\nBestellung: ${guestReceipt.order.id}\nBestellschlüssel: ${guestReceipt.guestKey}\n\nÖffne im Shop den Gastzugang und gib den Schlüssel ein. Vertraulich aufbewahren.\n`],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='NeonMind-Bestellzugang.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});

}

function route(){const canonical=document.querySelector('link[rel=canonical]');if(canonical)canonical.href='https://shop.neonmind-ai.com'+location.pathname;const robots=document.querySelector('meta[name=robots]');if(robots)robots.content=/^\/(account|login|register|downloads|checkout|guest|success|admin)(\/|$)/.test(location.pathname)?'noindex,nofollow':'index,follow';document.querySelectorAll('header nav a').forEach(a=>{if(a.getAttribute('href')==='/wuensche'&&routeHash()==='#wuensche')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});disposeSlider();disposeShelves();const page=(routeHash().slice(1)||'home').split('/')[0];updatePageFrame(page);dialog.close();if(page==='checkout'&&!catalogReady){view.innerHTML='<section class="page panel content"><h1>Deine Auswahl</h1><p role="status">'+(catalogFinished?'Der aktuelle Katalog konnte nicht geladen werden. Bitte lade die Seite erneut.':'Aktuelle Produkte und Preise werden geladen …')+'</p></section>';return;}if(['account','login','register'].includes(page))accountPage(page);else if(page==='admin'){view.innerHTML='<section class="page panel content"><h1>NeonMind Shop Verwaltung</h1><p>Dein geschützter Betreiberbereich.</p><button class="button primary" id="reopenAdmin">Admin Menü öffnen</button></section>';document.querySelector('#reopenAdmin').onclick=()=>window.openShopAdmin();window.openShopAdmin();}else if(page==='kontakt'){view.innerHTML='<section class="page panel content"><h1>Kontakt</h1><p>Fragen zum Shop oder zu deinem Projekt?</p><button class="button primary" id="reopenContact">Kontaktformular öffnen</button></section>';document.querySelector('#reopenContact').onclick=()=>window.openShopContact();window.openShopContact();}else if(page==='guest')guestPage();else if(page==='checkout')checkout();else if(page==='downloads')downloads();else previewRoute();window.scrollTo(0,0);if(page==='collections'&&Number.isFinite(history.state?.scrollY))requestAnimationFrame(()=>window.scrollTo({top:history.state.scrollY,behavior:'instant'}))}

async function refreshCatalog(){try{const responses=await Promise.all([fetch('/api/products'),fetch('/api/storefront')]);if(responses.some(r=>!r.ok))return;const [data,settings]=await Promise.all(responses.map(r=>r.json()));if(Array.isArray(data)){catalogReady=true;products=data.map(p=>Object.fromEntries(Object.entries(p).map(([k,v])=>[k,typeof v==='string'&&!['id','image','demo','category'].includes(k)?esc(v):v])));storefrontSettings=settings;cart=cart.filter(id=>find(id));save();}}catch{}}

refreshCatalog().then(()=>{catalogFinished=true;if(!['admin','kontakt'].includes((routeHash().slice(1)||'home').split('/')[0]))route();openRequestedCart()});

setupShopCore();setupIdentity();window.openShopArticles=()=>{if(location.pathname!=='/admin')history.pushState(null,'','/admin');adminPage();};

route();

async function adminPage(selectedId){view.innerHTML='<section class="page panel"><h1>Shop-Verwaltung</h1><p>Verwaltung wird geladen …</p></section>';try{const state=await api('/api/admin/state');if(routeHash()!=='#admin')return;const activeProducts=state.products.filter(p=>!p.deletedAt),trashedProducts=state.products.filter(p=>p.deletedAt);view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">NeonMind · Verwaltung</span><h1 style="font-size:40px">Dein Shop. Deine Designs.</h1><p><a class="button" href="/anfragen-admin.html">Anpassungsanfragen ansehen →</a></p><p>Produkte pflegen, Pakete hinterlegen und Bestellungen prüfen.</p><div class="benefits"><div><b>${activeProducts.length}</b> Produkte</div><div><b>${state.files.length}</b> private Pakete</div><div><b>${state.orders.length}</b> letzte Bestellungen</div></div><p class="notice">Zahlungsanschluss und Freischaltung findest du im Admin Menü unter Zahlungen & Testmodus. Geschützte Betreiber-Tests können die echten Paketdownloads prüfen.</p><section class="store-controls"><form id="sortForm"><h2>Anzeige im Shop</h2><label class="field">Produktreihenfolge<select name="productSort"><option value="newest">Neueste zuerst</option><option value="oldest">Älteste zuerst</option><option value="name">Name: A bis Z</option><option value="price-low">Preis: aufsteigend</option><option value="price-high">Preis: absteigend</option></select></label><button class="button" type="submit">Reihenfolge speichern</button></form><div><h2>Kategorien verwalten</h2><form id="categoryForm"><label class="field">Neue Kategorie<input name="name" required maxlength="40" placeholder="Zum Beispiel: Poster"></label><button class="button" type="submit">Kategorie hinzufügen</button></form><div class="category-list">${state.categories.map(c=>`<div><span>${esc(c)}</span>${c==='Sonstiges'?'<small>Auffangkategorie</small>':`<button class="button" data-delete-category="${esc(c)}">Löschen</button>`}</div>`).join('')}</div><p class="muted">Beim Löschen einer Kategorie bleiben ihre Produkte erhalten und wechseln zu Sonstiges.</p></div></section><p id="storeMessage" role="status"></p><div class="checkout-grid"><aside><h2>Deine Produkte</h2>${activeProducts.map(p=>`<p><button class="button" data-edit-product="${esc(p.id)}">${esc(p.name)} · ${p.published?'Sichtbar':'Entwurf'}</button></p>`).join('')}<button class="button primary" id="newProduct">＋ Neues Produkt</button><details class="product-trash"><summary>Papierkorb (${trashedProducts.length})</summary><p class="muted">Gelöschte Produkte sind aus dem Angebot entfernt. Pakete und Bestellungen bleiben erhalten.</p>${trashedProducts.length?trashedProducts.map(p=>`<div class="trash-item"><span>${esc(p.name)}</span><button class="button" data-restore-product="${esc(p.id)}">Wiederherstellen</button></div>`).join(''):'<p class="muted">Der Papierkorb ist leer.</p>'}</details></aside><div><form id="productForm"><h2 id="editorTitle">Produkt bearbeiten</h2><label class="field">Produktkennung<input name="id" pattern="[a-z0-9-]{1,48}" required maxlength="48" aria-describedby="productIdHelp" title="1 bis 48 Zeichen: Kleinbuchstaben, Zahlen oder Bindestriche."></label><p id="productIdHelp" class="muted">Zum Beispiel: aurora-nights. Kleinbuchstaben, Zahlen und Bindestriche; Großbuchstaben werden automatisch angepasst.</p><label class="field">Name<input name="name" required maxlength="120"></label><label class="field">Kategorie<select name="category">${state.categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label class="field">Preis in Euro<input name="price" type="number" min="0" max="10000" step="0.01" required></label><label class="field">Beschreibung<textarea name="description" required maxlength="2000" rows="3"></textarea></label><label class="field">Lieferumfang<input name="contents" required maxlength="2000"></label><label class="field">Dateiformate<input name="formats" required maxlength="2000"></label><label class="field">Motivvorschau<select name="image"><option value="assets/aurora.png">Aurora Nights</option><option value="assets/flow.png">Neon Flow</option><option value="assets/stream.png">Stream Essentials</option></select></label><label class="check"><input name="published" type="checkbox">Im Shop anzeigen</label><button class="button primary" type="submit">Produkt speichern</button><button class="button danger" type="button" id="deleteProduct" hidden>Produkt löschen</button><div id="deleteConfirmation" hidden><p id="deleteQuestion"></p><p class="muted">Das Produkt wird in den Papierkorb verschoben und kann wiederhergestellt werden.</p><button class="button danger" type="button" id="confirmDeleteProduct">In Papierkorb verschieben</button><button class="button" type="button" id="cancelDeleteProduct">Abbrechen</button></div></form><form id="previewUpload"><h2>Eigenes Vorschaubild</h2><label class="field">PNG oder JPG · maximal 5 MB<input id="previewFile" type="file" accept="image/png,image/jpeg" required></label><button class="button" type="submit">Vorschaubild hochladen</button><p class="muted">Dieses Bild ist öffentlich sichtbar. Anschließend das Produkt speichern.</p></form><form id="uploadForm"><h2>Privates Downloadpaket</h2><p id="packageState" class="muted"></p><a id="adminPackageDownload" class="button" hidden>Vorhandenes Paket prüfen ↓</a><label class="field">ZIP-Datei · maximal 50 MB<input id="packageFile" type="file" accept=".zip,application/zip" required></label><button class="button" type="submit">Paket hochladen</button><p class="muted">Das Paket ersetzt die bisherige Datei dieses Produkts. Es erhält keine öffentliche Adresse.</p></form><p id="adminMessage" role="status"></p></div></div><h2>Letzte Bestellungen</h2>${state.orders.length?state.orders.map(o=>`<div class="summary-line"><span>${esc(o.id.slice(0,8))} · ${new Date(o.created_at).toLocaleDateString('de-DE')}</span><span>${money(o.amount)} · ${esc(o.status)}</span></div>`).join(''):'<p class="muted">Noch keine Bestellungen.</p>'}</div></section>`;

const storeMessage=$('#storeMessage');$('#sortForm').elements.productSort.value=state.productSort;

$('#sortForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/settings',{productSort:e.target.elements.productSort.value});await refreshCatalog();storeMessage.textContent='Reihenfolge gespeichert.'}catch(error){storeMessage.textContent=error.message}};

$('#categoryForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/category',{action:'add',name:e.target.elements.name.value});await refreshCatalog();await adminPage(selectedId);toast('Kategorie hinzugefügt.')}catch(error){storeMessage.textContent=error.message}};

document.querySelectorAll('[data-delete-category]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/admin/category',{action:'delete',name:button.dataset.deleteCategory});await refreshCatalog();await adminPage(selectedId);toast('Kategorie entfernt. Produkte bleiben erhalten.')}catch(error){storeMessage.textContent=error.message;button.disabled=false}});

const form=$('#productForm'),message=$('#adminMessage');let savedId='';const edit=p=>{savedId=p?.id||'';form.reset();$('#deleteProduct').hidden=!p;$('#deleteConfirmation').hidden=true;for(const name of ['id','name','category','description','contents','formats','image'])if(p){if(name==='image'&&p.image.startsWith('/api/preview/'))form.elements.image.add(new Option('Eigenes Vorschaubild',p.image));form.elements[name].value=p[name];}form.elements.id.readOnly=!!p;form.elements.price.value=p?p.price/100:'';form.elements.published.checked=!!p?.published;const file=state.files.find(f=>f.product_id===savedId);$('#adminPackageDownload').hidden=!file;$('#adminPackageDownload').href='/api/admin/package/'+savedId;$('#packageState').textContent=file?`${file.filename} · ${(file.size/1048576).toFixed(2)} MB`:'Noch kein Paket hinterlegt.';$('#uploadForm').hidden=!p;$('#previewUpload').hidden=!p;};edit(activeProducts.find(p=>p.id===selectedId)||activeProducts[0]);form.elements.id.addEventListener('input',()=>{form.elements.id.value=form.elements.id.value.toLowerCase()});document.querySelectorAll('[data-edit-product]').forEach(button=>button.onclick=()=>edit(state.products.find(p=>p.id===button.dataset.editProduct)));$('#newProduct').onclick=()=>edit(null);

$('#deleteProduct').onclick=()=>{const p=activeProducts.find(p=>p.id===savedId);if(!p)return;$('#deleteQuestion').textContent='„'+p.name+'“ aus dem Shop löschen?';$('#deleteConfirmation').hidden=false;};

$('#cancelDeleteProduct').onclick=()=>{$('#deleteConfirmation').hidden=true;};

$('#confirmDeleteProduct').onclick=async e=>{if(!savedId)return;e.target.disabled=true;try{await api('/api/admin/product-trash',{id:savedId,action:'delete'});await refreshCatalog();await adminPage();toast('Produkt in den Papierkorb verschoben.')}catch(error){message.textContent=error.message;e.target.disabled=false}};

document.querySelectorAll('[data-restore-product]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/admin/product-trash',{id:button.dataset.restoreProduct,action:'restore'});await refreshCatalog();await adminPage(button.dataset.restoreProduct);toast('Produkt wiederhergestellt.')}catch(error){message.textContent=error.message;button.disabled=false}});

form.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form));b.price=Math.round(Number(b.price)*100);b.published=form.elements.published.checked;const button=form.querySelector('[type=submit]');button.disabled=true;try{await api('/api/admin/product',b);await refreshCatalog();await adminPage(b.id);toast('Produkt gespeichert.')}catch(error){message.textContent=error.message;button.disabled=false}};

$('#previewUpload').onsubmit=async e=>{e.preventDefault();const file=$('#previewFile').files[0];const button=e.target.querySelector('button');button.disabled=true;try{if(!file||file.size>5*1048576)throw Error('Bitte ein Bild bis 5 MB wählen.');const r=await fetch('/api/admin/upload-preview/'+savedId,{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);form.elements.image.add(new Option('Eigenes Vorschaubild',data.image));form.elements.image.value=data.image;message.textContent='Vorschaubild hochgeladen. Bitte Produkt speichern.'}catch(error){message.textContent=error.message}finally{button.disabled=false}};

$('#uploadForm').onsubmit=async e=>{e.preventDefault();const file=$('#packageFile').files[0];if(!file||file.size>50*1048576){message.textContent='Bitte eine ZIP-Datei bis 50 MB wählen.';return}const button=e.target.querySelector('button');button.disabled=true;message.textContent='Paket wird hochgeladen …';try{const response=await fetch('/api/admin/upload/'+savedId,{method:'POST',headers:{'Content-Type':'application/zip'},body:file});const result=await response.json();if(!response.ok)throw Error(result.error);await adminPage(savedId);toast('Privates Paket gespeichert.')}catch(error){message.textContent=error.message;button.disabled=false}};

}catch(error){view.innerHTML=`<section class="page panel content"><span class="kicker">Geschützter Bereich</span><h1 style="font-size:40px">Shop-Verwaltung</h1><p>${esc(error.message)}</p><a class="button primary" href="/login">Mit Betreiberkonto anmelden</a><p><a href="/">Zurück zum Shop</a></p></section>`}}



// Discourage casual saving of public preview images; text and form menus stay available.

document.addEventListener('contextmenu',e=>{if(e.target instanceof Element&&e.target.closest('img'))e.preventDefault();});

document.addEventListener('dragstart',e=>{if(e.target instanceof Element&&e.target.closest('img'))e.preventDefault();});



async function wishesPage(){

 view.innerHTML='<div class="wishes-integrated"><p class="wishes-loading" role="status">Deine Projektanfrage wird geladen …</p></div>';

 document.title='Deine Wünsche · NeonMind Shop';

 try{const response=await fetch('/deine-wuensche.html');if(!response.ok)throw Error('load');const doc=new DOMParser().parseFromString(await response.text(),'text/html');const main=doc.querySelector('main');if(!main)throw Error('content');if(routeHash()!=='#wuensche')return;view.innerHTML='<div class="wishes-integrated">'+main.innerHTML+'</div>';window.mountNeonMindInquiry(view);}catch{if(routeHash()==='#wuensche')view.innerHTML='<div class="panel"><h1>Deine Wünsche</h1><p>Die Anfrage konnte gerade nicht geladen werden.</p><a class="button" href="/wuensche" onclick="location.reload()">Erneut laden →</a></div>';}

}


document.addEventListener('click',event=>{const b=event.target.closest('[data-order-design],[data-save-design]');if(!b)return;try{const design=JSON.parse(decodeURIComponent(b.dataset.orderDesign||b.dataset.saveDesign));if(b.dataset.orderDesign){localStorage.setItem('nm-design-draft',JSON.stringify(design));location.href='/gestalter.html?review=1&package='+encodeURIComponent(design.productId||'designstudio')+'&category='+encodeURIComponent(design.category);}else{const u=URL.createObjectURL(new Blob([JSON.stringify(design,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='NeonMind-Entwurf.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}}catch{toast('Entwurf konnte nicht geöffnet werden.')}});

// Private ZIP downloads always require server-side ownership and payment checks.
document.addEventListener('click',async e=>{const b=e.target.closest('[data-paid-download]');if(!b)return;b.disabled=true;try{const response=await fetch('/api/download',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({orderId:b.dataset.orderId,productId:b.dataset.paidDownload,key:$('#guestKey')?.value.trim()||guestReceipt?.guestKey||''})});if(!response.ok){let error;try{error=await response.json()}catch{}throw Error(error?.error||'Download nicht verfügbar.');}const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'NeonMind-Paket.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}catch(err){toast(err.message)}finally{b.disabled=false}});

function openRequestedCart(){if(new URLSearchParams(location.search).get('cart')==='open'){
 document.querySelector('#cartButton').click();
 const url=new URL(location.href);url.searchParams.delete('cart');history.replaceState(null,'',url.pathname+url.search);
}
}


